import {defineConfig }from'vite';
importreactfrom'@vitejs/plugin-react';

exportdefaultdefineConfig({
  plugins: [react()],
  server: {
    port:3000,
    open:true,
  },
  build: {
    target:'esnext',
    sourcemap:true,
  },
});

import {defineConfig }from'@turbopack/dev-server';
importreactRefreshfrom'@turbopack/react-refresh';

exportdefaultdefineConfig({
  entry:'./src/index.tsx',
  plugins: [reactRefresh()],
  devServer: {
    port:3000,
    hot:true,
  },
  optimization: {
    minify:true,
    target:'es2022',
  },
});

constReactRefreshWebpackPlugin=require('@pmmmwh/react-refresh-webpack-plugin');

module.exports= {
  entry:'./src/index.tsx',
  mode:'development',
  devServer: {
    hot:true,
    port:3000,
    open:true,
  },
  module: {
    rules: [
      {
        test:/\.(ts|tsx)$/,
        use:'babel-loader',
        exclude:/node_modules/,
      },
    ],
  },
  plugins: [newReactRefreshWebpackPlugin()],
  resolve: {
    extensions: ['.tsx','.ts','.js'],
  },
};
